/**
 * /coverage — public-facing data quality dashboard (Track GG.3).
 *
 * Reads data/quality/coverage_v2.json (generated by audit_coverage.py)
 * and renders a filterable table + headline stats. Trust signal: honest
 * accounting of where data is strong vs weak.
 */
import fs from "node:fs";
import path from "node:path";
import Link from "next/link";
import { COUNTRIES } from "@/lib/taxonomy";

export const revalidate = 21600; // 6 hours

type CoverageReport = {
  generated_at: string;
  totals: {
    countries: number;
    regional_cells_total: number;
    extrapolated_cells_total: number;
    industries_covered: number;
  };
  countries: Array<{
    iso2: string;
    regional_cells: number;
    extrapolated_cells: number;
    industries: number;
    geographies: number;
    tiers: Record<string, number>;
    avg_quality: number;
    avg_quality_10: number;
    year_range: [number | null, number | null];
  }>;
};

function loadReport(): CoverageReport | null {
  const candidates = [
    path.resolve(process.cwd(), "data/quality/coverage_v2.json"),
    path.resolve(process.cwd(), "delivery/quality/coverage_v2.json"),
    path.resolve(process.cwd(), "../delivery/quality/coverage_v2.json"),
  ];
  for (const p of candidates) {
    try {
      return JSON.parse(fs.readFileSync(p, "utf-8")) as CoverageReport;
    } catch {
      continue;
    }
  }
  return null;
}

function qualityClass(q: number): string {
  if (q >= 7) return "bg-moss-100 text-moss-800";
  if (q >= 5) return "bg-cream-100 text-ink-900";
  if (q >= 3) return "bg-clay-100 text-clay-800";
  return "bg-clay-100 text-clay-900";
}

function countryName(iso2: string): string {
  const c = COUNTRIES.find((c) => c.code === iso2);
  return c?.name || iso2;
}

export const metadata = {
  title: "Coverage report: Margin Atlas",
  description:
    "Per-country data quality and coverage across Margin Atlas.",
};

export default async function CoveragePage() {
  const report = loadReport();

  if (!report) {
    return (
      <div className="py-12 max-w-3xl">
        <h1 className="text-3xl font-semibold tracking-tight text-ink-900">
          Coverage report
        </h1>
        <p className="mt-4 text-ink-700">
          Coverage data is being prepared: check back shortly. (No
          coverage_v2.json on disk yet.)
        </p>
      </div>
    );
  }

  const sortedByCells = [...report.countries].sort(
    (a, b) => b.regional_cells + b.extrapolated_cells - (a.regional_cells + a.extrapolated_cells)
  );
  const topCovered = sortedByCells.slice(0, 12);
  const mostNeeded = [...report.countries]
    .filter((c) => c.regional_cells + c.extrapolated_cells > 0)
    .sort((a, b) => a.avg_quality - b.avg_quality)
    .slice(0, 10);

  return (
    <div className="py-12">
      <header className="max-w-3xl">
        <div className="text-xs uppercase tracking-wide text-atlas-600 font-medium">
          Trust signal
        </div>
        <h1 className="mt-2 text-3xl md:text-4xl font-semibold tracking-tight text-ink-900">
          Coverage report
        </h1>
        <p className="mt-3 text-ink-700 leading-relaxed">
          Honest accounting of where Margin Atlas data is strong, weak, or
          missing. Updated periodically from a full audit of the underlying
          tables. Last refresh:{" "}
          <time className="font-medium text-ink-900">
            {report.generated_at.slice(0, 10)}
          </time>
          .
        </p>
      </header>

      <section className="mt-8 grid grid-cols-2 md:grid-cols-4 gap-3">
        {[
          [report.totals.countries.toLocaleString(), "countries with data"],
          [
            (report.totals.regional_cells_total + report.totals.extrapolated_cells_total).toLocaleString(),
            "total benchmarks",
          ],
          [report.totals.regional_cells_total.toLocaleString(), "measured / sub-national"],
          [report.totals.industries_covered.toLocaleString(), "industries"],
        ].map(([n, label]) => (
          <div
            key={label}
            className="rounded-2xl bg-cream-100 border border-parchment p-5"
          >
            <div className="text-3xl font-semibold text-ink-900 tabular-nums">
              {n}
            </div>
            <div className="text-sm text-ink-800 mt-1">{label}</div>
          </div>
        ))}
      </section>

      <section className="mt-12">
        <h2 className="text-xl font-semibold text-ink-900 mb-3">
          Best-covered countries
        </h2>
        <div className="grid sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-2">
          {topCovered.map((c) => (
            <Link
              key={c.iso2}
              href={`/coverage/${c.iso2.toLowerCase()}`}
              className="block p-4 rounded-xl border border-ink-200 bg-white hover:border-atlas-500 transition"
            >
              <div className="flex items-center justify-between">
                <div className="font-semibold text-ink-900 text-sm">
                  {countryName(c.iso2)}
                </div>
                <span
                  className={`px-2 py-0.5 rounded-full text-xs font-medium ${qualityClass(
                    c.avg_quality_10
                  )}`}
                >
                  q={c.avg_quality_10}
                </span>
              </div>
              <div className="mt-1 text-xs text-ink-700/70">
                {(c.regional_cells + c.extrapolated_cells).toLocaleString()} benchmarks ·{" "}
                {c.industries} industries
              </div>
            </Link>
          ))}
        </div>
      </section>

      {mostNeeded.length > 0 ? (
        <section className="mt-12">
          <h2 className="text-xl font-semibold text-ink-900 mb-1">
            Most-needed countries
          </h2>
          <p className="text-sm text-ink-800 mb-3">
            Countries where our confidence is lowest: first up for refinement.
          </p>
          <div className="grid sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-2">
            {mostNeeded.map((c) => (
              <Link
                key={c.iso2}
                href={`/coverage/${c.iso2.toLowerCase()}`}
                className="block p-3 rounded-xl border border-ink-200 bg-white hover:border-atlas-500 transition text-xs"
              >
                <div className="font-semibold text-ink-900">{countryName(c.iso2)}</div>
                <div className="mt-1 text-ink-700/70">
                  q={c.avg_quality_10} · {(c.regional_cells + c.extrapolated_cells).toLocaleString()} benchmarks
                </div>
              </Link>
            ))}
          </div>
        </section>
      ) : null}

      <section className="mt-12">
        <h2 className="text-xl font-semibold text-ink-900 mb-3">
          Full coverage table
        </h2>
        <div className="overflow-x-auto rounded-xl border border-ink-200">
          <table className="w-full text-sm">
            <thead className="bg-cream-100 text-ink-900">
              <tr className="text-left">
                <th className="py-2 px-3">Country</th>
                <th className="py-2 px-3 text-right">Regional</th>
                <th className="py-2 px-3 text-right">Extrapolated</th>
                <th className="py-2 px-3 text-right">Industries</th>
                <th className="py-2 px-3 text-right">Quality (1-10)</th>
              </tr>
            </thead>
            <tbody>
              {sortedByCells.map((c) => (
                <tr key={c.iso2} className="border-t border-ink-200/40">
                  <td className="py-1.5 px-3">
                    <Link
                      href={`/coverage/${c.iso2.toLowerCase()}`}
                      className="text-ink-900 hover:text-atlas-700"
                    >
                      {countryName(c.iso2)}{" "}
                      <span className="text-ink-700/60 font-mono text-xs">
                        {c.iso2}
                      </span>
                    </Link>
                  </td>
                  <td className="py-1.5 px-3 text-right tabular-nums">
                    {c.regional_cells.toLocaleString()}
                  </td>
                  <td className="py-1.5 px-3 text-right tabular-nums">
                    {c.extrapolated_cells.toLocaleString()}
                  </td>
                  <td className="py-1.5 px-3 text-right tabular-nums">
                    {c.industries}
                  </td>
                  <td className="py-1.5 px-3 text-right">
                    <span
                      className={`px-2 py-0.5 rounded-full text-xs font-medium ${qualityClass(
                        c.avg_quality_10
                      )}`}
                    >
                      {c.avg_quality_10}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}
